251	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
252	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
253	
254	    /**
255	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
256	     * code are kept when present; otherwise country code '+61' is assumed and a single
257	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
258	     * stripped. The result must be a '+' followed by 8 to 15 digits.
259	     * Returns {@code null} when the number cannot form a valid E.164 value.
260	     */
261	    private static String normalizeTelephone(String telephone) {
262	        if (telephone == null) {
263	            return null;
264	        }
265	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
266	        String e164;
267	        if (cleaned.startsWith("+")) {
268	            e164 = cleaned;
269	        } else {
270	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
271	            e164 = "+61" + national;
272	        }
273	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
274	    }
275	
276	    /**
277	     * Build the customer code '<LAST3>-<NNNN>': LAST3 is the upper-cased first three letters
278	     * of {@code lastName} and NNNN is a global 4-digit zero-padded sequence equal to one more
279	     * than the current number of owners (e.g. 'SMI-0007').
280	     */
281	    private String generateCustomerCode(String lastName) {
282	        String letters = lastName.replaceAll("[^\\p{L}]", "");
283	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
284	        int sequence = this.clinicService.findAllOwners().size() + 1;
285	        return String.format("%s-%04d", last3, sequence);
286	    }
287	
288	    /**
289	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
290	     * last name, compared case-insensitively.
291	     */
292	    private int countNamesakes(Owner owner) {
293	        String firstName = normalizeHouseholdField(owner.getFirstName());
294	        String lastName = normalizeHouseholdField(owner.getLastName());
295	        return (int) this.clinicService.findAllOwners().stream()
296	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
297	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
298	            .count();
299	    }
