301	    /** Whether any existing owner already uses the given (E.164) telephone number. */
302	    private boolean isTelephoneInUse(String telephone) {
303	        return this.clinicService.findAllOwners().stream()
304	            .map(Owner::getTelephone)
305	            .filter(existing -> existing != null)
306	            .map(OwnerRestControllerV1::normalizeTelephone)
307	            .filter(existing -> existing != null)
308	            .anyMatch(telephone::equals);
309	    }
310	
311	    /** Common street-type abbreviations expanded during address normalization. */
312	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
313	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
314	
315	    /**
316	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
317	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
318	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
319	     * string when {@code address} is null or blank after normalization.
320	     */
321	    private static String normalizeAddress(String address) {
322	        if (address == null) {
323	            return "";
324	        }
325	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
326	        if (collapsed.isEmpty()) {
327	            return "";
328	        }
329	        StringBuilder sb = new StringBuilder(collapsed.length());
330	        for (String token : collapsed.split(" ")) {
331	            if (sb.length() > 0) {
332	                sb.append(' ');
333	            }
334	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
335	        }
336	        return sb.toString();
337	    }
338	
339	    /**
340	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
341	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
342	     */
343	    private static String normalizeHouseholdField(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
352	     * same address compared case-insensitively with collapsed whitespace.
353	     */
354	    private List<Owner> findHousemates(Owner owner) {
355	        String lastName = normalizeHouseholdField(owner.getLastName());
356	        String address = normalizeHouseholdField(owner.getAddress());
357	        return this.clinicService.findAllOwners().stream()
358	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
359	                && normalizeHouseholdField(existing.getAddress()).equals(address))
360	            .toList();
361	    }
362	
363	    /**
364	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
365	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
366	     */
367	    private boolean isHouseholdInUse(Owner owner) {
368	        return !findHousemates(owner).isEmpty();
369	    }
370	
371	    /**
372	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
373	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
374	     * deterministically from those normalized fields so housemates always resolve to the same value,
375	     * regardless of registration order.
376	     */
377	    private static String householdId(Owner owner) {
378	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
379	            + normalizeHouseholdField(owner.getAddress());
380	        try {
381	            byte[] digest = MessageDigest.getInstance("SHA-256")
382	                .digest(key.getBytes(StandardCharsets.UTF_8));
383	            StringBuilder sb = new StringBuilder(24);
384	            for (int i = 0; i < 12; i++) {
385	                sb.append(String.format("%02X", digest[i]));
386	            }
387	            return sb.toString();
388	        }
389	        catch (NoSuchAlgorithmException e) {
390	            throw new IllegalStateException("SHA-256 not available", e);
391	        }
392	    }
393	}
